/* @lc app=leetcode id=3946 lang=kotlin */ class Solution { fun maximumSaleItems(items: Array<IntArray>, budget: Int): Int = IntArray(1501).also { c -> items.forEach { c[it[0]]++ } }.let { cnt -> IntArray(1501).also { s -> (1..1500).forEach { d -> (d..1500 step d).forEach { s[d] += cnt[it] } } }.let { s -> items.fold(IntArray(budget + 1) { if (it == 0) 0 else -1_000_000 }) { d, (f, p) -> IntArray(budget + 1) { b -> if (b >= p && d[b - p] >= 0) maxOf(d[b], d[b - p] + s[f]) else d[b] } }.let { dp -> items.minOf { it[1] }.let { pm -> (0..budget).maxOf { b -> if (dp[b] >= 0) dp[b] + (budget - b) / pm else 0 } } } } } }